typeDefinitions.content:
export type ErrorCode = | "INVALID_REQUEST" | "INVALID_CREDENTIALS" | "CAPTCHA_REQUIRED" | "CAPTCHA_FAILED" | "LOGIN_FAILED" | "SESSION_EXPIRED" | "EDUVULCAN_UNAVAILABLE" | "MOBILE_API_UNAVAILABLE" | "RATE_LIMITED" | "INTERNAL_ERROR";
export interface APIError { code: ErrorCode; message: string; }
export interface APIResponse<T> { success: boolean; data?: T; error?: APIError; }
export interface Student { id: string; name: string; surname: string; class: string; school: string; }
export interface Grade { id: string; subjectId: string; subjectName: string; value: string; numericValue?: number; type: string; date: string; weight: number; }
export interface AttendanceSummary { present: number; absent: number; late: number; excused: number; unknown: number; }
export interface AttendanceEntry { date: string; lesson: number; subject: string; status: "present" | "absent" | "late" | "excused" | "unknown"; }
export interface AttendanceData { summary: AttendanceSummary; entries: AttendanceEntry[]; }
export interface Lesson { date: string; lessonNumber: number; start: string; end: string; subject: string; teacher: string; room: string; }
export interface Subject { id: string; name: string; teacher: string; }
export interface VulcanEvent { id: string; title: string; description?: string; type: "assignment" | "test" | "exam" | "grade" | "note" | "event"; subject?: string; date: Date; dueDate?: Date; completed: boolean; priority: "low" | "normal" | "high"; color?: string; }
export interface VulcanGrade { id: string; subject: string; title: string; value: number; displayValue?: string; weight: number; teacher: string; date: Date; comment?: string; }
export interface VulcanGradeSummary { subject: string; average: number; count: number; grades: VulcanGrade[]; }
export interface ApiApPayload { Success?: boolean; Tokens?: string[]; Alias?: string; GivenName?: string; Surname?: string; AccessToken?: string; IsConsentAccepted?: boolean; CanAcceptConsent?: boolean; }
export interface MobileStudent { PupilId: number; FirstName: string; LastName: string; Pupil?: { ClassDisplay?: string; ConstituentUnit?: { Name?: string }; Unit?: { Id?: number; Symbol?: string; Name?: string }; Pupil?: { Id?: number }; Periods?: Array<{ Id: number; Current?: boolean }>; }; }
export interface MobileGrade { Id: string | number; Value: string | number; ContentRaw?: string | number | null; Content?: string | number | null; Column?: { Subject?: { Id?: string | number; Name?: string }; Weight?: string | number; Name?: string; }; DateCreated?: { Timestamp?: number }; Creator?: { DisplayName?: string }; }
export interface MobileLesson { Id: string | number; Subject?: { Name?: string }; TeacherPrimary?: { DisplayName?: string }; Room?: { Code?: string } | null; Date?: { Timestamp?: number; Date?: string }; LessonNumber?: number; TimeSlot?: { Start?: string; End?: string }; }
export interface MobileHomework { Id: string | number; Content?: string; Subject?: { Name?: string }; Deadline?: { Timestamp?: number }; }
export interface MobileExam { Id: string | number; Content?: string; Type?: string; Subject?: { Name?: string }; Deadline?: { Timestamp?: number; Date?: string }; DateCreated?: { Timestamp?: number; Date?: string }; }
export interface MobileAttendance { Id: string | number; LessonId?: string | number; Day?: { Timestamp?: number; Date?: string }; LessonNumber?: number; Subject?: { Name?: string }; PresenceType?: { Name?: string; Presence?: boolean; Absence?: boolean; Late?: boolean; AbsenceJustified?: boolean; Removed?: boolean; }; }
export interface MobileSession { id: string; keypair: MobileKeypair; restUrl: string; student: MobileStudent; account: { fullName: string; studentId?: number }; createdAt: string; }
export interface MobileKeypair { fingerprint: string; privateKey: string; certificate: string; }
export interface GradeCalculationResult { weightedAverage: number; simpleAverage: number; gradeCount: number; categoryAverages: Record<string, number>; }
export interface AttendanceRateResult { presentRate: number; absenceRate: number; lateRate: number; excusedRate: number; warningThresholdMet: boolean; }
